import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"How do I install the adapter and what if the instance does not start?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/01.erste-schritte/02.installation.md"},"headers":[],"relativePath":"adapter/esphome/erste-schritte/installation.md","filePath":"adapter/esphome/erste-schritte/installation.md","lastUpdated":1795571670000}'),n={name:"adapter/esphome/erste-schritte/installation.md"};function s(i,e,d,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="how-do-i-install-the-adapter-and-what-if-the-instance-does-not-start" tabindex="-1">How do I install the adapter and what if the instance does not start? <a class="header-anchor" href="#how-do-i-install-the-adapter-and-what-if-the-instance-does-not-start" aria-label="Permalink to &quot;How do I install the adapter and what if the instance does not start?&quot;">​</a></h1><p><a id="install-older-version-pre-release"></a></p><h2 id="how-do-i-install-an-older-version-or-a-pre-release" tabindex="-1">How do I install an older version or a pre-release? <a class="header-anchor" href="#how-do-i-install-an-older-version-or-a-pre-release" aria-label="Permalink to &quot;How do I install an older version or a pre-release?&quot;">​</a></h2><p>You install pre-releases and older versions on the console of the ioBroker host. The ioBroker repository does not offer pre-releases.</p><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>current pre-release</td><td><code>iobroker url iobroker.esphome@next</code></td></tr><tr><td>a specific version</td><td><code>iobroker url iobroker.esphome@2.0.0-beta.2</code></td></tr><tr><td>back to the released version</td><td><code>iobroker url iobroker.esphome</code></td></tr></tbody></table><p>All versions with their changes are listed under <a href="https://github.com/DrozmotiX/ioBroker.esphome/releases" target="_blank" rel="noreferrer">Releases</a>. The instance and its settings stay when you switch. If you install the adapter this way for the first time, ioBroker creates no instance. Then add it yourself in admin, tab &quot;Adapters&quot;.</p><p><a id="instance-stay-red-after-install"></a></p><h2 id="why-does-the-instance-stay-red-after-install-or-update" tabindex="-1">Why does the instance stay red after install or update? <a class="header-anchor" href="#why-does-the-instance-stay-red-after-install-or-update" aria-label="Permalink to &quot;Why does the instance stay red after install or update?&quot;">​</a></h2><p>The instance is green while the adapter runs. This is <code>esphome.0.info.connection</code>. Whether devices are connected does not change it. The connected devices are listed in <code>esphome.0.info.connectedDevices</code>.</p><p>If the instance stays red, the adapter is not running. The reason is in the log of the instance:</p><ol><li>Open the tab &quot;Log&quot; in admin and filter for <code>esphome.0</code>.</li><li>If it mentions the Node.js version, install Node.js 22.12 or newer.</li><li>If it shows an error while loading the adapter, install it again, e.g. with <code>iobroker url iobroker.esphome</code>, and start the instance.</li></ol><p>A dashboard that does not start does not turn the instance red. The error is then in the log and the reason in the tab &quot;ESPHome Dashboard&quot;.</p><p><strong>See also:</strong> <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Why does the dashboard not start?</a></p><p><a id="adapter-not-installed-compiled-after"></a></p><h2 id="why-can-the-adapter-not-be-installed-or-compiled-after-restoring-a-backup" tabindex="-1">Why can the adapter not be installed or compiled after restoring a backup? <a class="header-anchor" href="#why-can-the-adapter-not-be-installed-or-compiled-after-restoring-a-backup" aria-label="Permalink to &quot;Why can the adapter not be installed or compiled after restoring a backup?&quot;">​</a></h2><p>A restore brings back the settings and states. ioBroker installs the adapter again, possibly in an older version. The Python environment of the dashboard lives outside ioBroker and is not part of the backup.</p><p>This gets everything running again:</p><ol><li>Check the installed version in admin, tab &quot;Adapters&quot;. If it is old, install the current one, e.g. with <code>iobroker url iobroker.esphome</code>.</li><li>If the dashboard does not start, press &quot;Reset Python environment&quot; in the tab &quot;ESPHome Dashboard&quot; and restart the instance. The adapter builds the environment again at startup.</li><li>Check in the tab &quot;Devices&quot; that all devices are connected.</li></ol><p><strong>See also:</strong> <a href="./../anleitungen/yaml-dateien#back-up-restore-esphome-files">Back up and restore the ESPHome files</a> · <a href="./../fehlerbehebung/dashboard-startet-nicht#clear-autopy-cache-if-python">Reset the Python environment</a></p>',19)])])}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
